CREATE TABLE "places" (
	"id" integer PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"aka" text,
	"name_si" text,
	"name_ta" text,
	"district" text NOT NULL,
	"province" text NOT NULL,
	"location" geography(Point,4326) NOT NULL,
	"approximate" boolean DEFAULT false NOT NULL,
	"main" boolean DEFAULT false NOT NULL
);
--> statement-breakpoint
CREATE EXTENSION IF NOT EXISTS pg_trgm;--> statement-breakpoint
CREATE INDEX "places_name_trgm_idx" ON "places" USING gin (lower("name") gin_trgm_ops);--> statement-breakpoint
CREATE INDEX "places_aka_trgm_idx" ON "places" USING gin (lower("aka") gin_trgm_ops);--> statement-breakpoint
-- 2145 towns. Generated by scripts/places/build.ts; don't edit by hand.
ON CONFLICT ("id") DO UPDATE SET "name" = excluded."name", "aka" = excluded."aka", "name_si" = excluded."name_si", "name_ta" = excluded."name_ta", "district" = excluded."district", "province" = excluded."province", "location" = excluded."location", "main" = excluded."main";
--> statement-breakpoint
UPDATE "places" p SET "approximate" = (p."name" <> p."district" AND (SELECT count(*) FROM "places" q WHERE ST_Equals(q."location"::geometry, p."location"::geometry)) >= 3);--> statement-breakpoint
ALTER TABLE "profiles" ADD COLUMN "place_id" integer DEFAULT 1841 NOT NULL;--> statement-breakpoint
-- The eight areas people could pick before, as towns.
UPDATE "profiles" SET "place_id" = CASE "area"
  WHEN 'Colombo 03' THEN 1838 WHEN 'Colombo 05' THEN 1840 WHEN 'Colombo 07' THEN 1841
  WHEN 'Dehiwala' THEN 340 WHEN 'Nugegoda' THEN 362 WHEN 'Rajagiriya' THEN 1885
  WHEN 'Mount Lavinia' THEN 359 WHEN 'Battaramulla' THEN 334 ELSE 1841 END;--> statement-breakpoint
UPDATE "activities" SET "area" = CASE "area"
  WHEN 'Colombo 03' THEN 'Colombo 3' WHEN 'Colombo 05' THEN 'Colombo 5' WHEN 'Colombo 07' THEN 'Colombo 7'
  ELSE "area" END;--> statement-breakpoint
CREATE INDEX "places_location_gix" ON "places" USING gist ("location");--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_place_id_places_id_fk" FOREIGN KEY ("place_id") REFERENCES "public"."places"("id") ON DELETE no action ON UPDATE no action;